#include <algorithm>
#include <fstream>
#include <vector>
int highWins(std::vector<int> b, std::vector<int> e) {
    std::sort(b.begin(), b.end());
    std::sort(e.begin(), e.end());
    int matched = 0;
    for (int card : b) {
        if (matched < static_cast<int>(e.size()) && card > e[matched]) ++matched;
    }
    return matched;
}
int main() {
    std::ifstream in("cardgame.in");
    std::ofstream out("cardgame.out");
    int n;
    in >> n;
    std::vector<int> e(n), b;
    std::vector<bool> used(2 * n + 1, false);
    for (int& card : e) { in >> card; used[card] = true; }
    for (int card = 1; card <= 2 * n; ++card) if (!used[card]) b.push_back(card);
    int half = n / 2;
    std::vector<int> highB(b.begin() + half, b.end());
    std::vector<int> highE(e.begin(), e.begin() + half);
    std::vector<int> lowB, lowE;
    for (int i = 0; i < half; ++i) lowB.push_back(2 * n + 1 - b[i]);
    for (int i = half; i < n; ++i) lowE.push_back(2 * n + 1 - e[i]);
    out << highWins(highB, highE) + highWins(lowB, lowE) << '\n';
}
