#include <algorithm>
#include <fstream>
#include <vector>
int main() {
    std::ifstream in("feast.in");
    std::ofstream out("feast.out");
    int t, a, b;
    in >> t >> a >> b;
    std::vector<unsigned char> before(t + 1, 0), after(t + 1, 0);
    before[0] = 1;
    for (int f = 0; f <= t; ++f) {
        if (!before[f]) continue;
        if (f + a <= t) before[f + a] = 1;
        if (f + b <= t) before[f + b] = 1;
    }
    for (int f = 0; f <= t; ++f) if (before[f]) after[f / 2] = 1;
    for (int f = 0; f <= t; ++f) {
        if (!after[f]) continue;
        if (f + a <= t) after[f + a] = 1;
        if (f + b <= t) after[f + b] = 1;
    }
    for (int f = t; f >= 0; --f) {
        if (before[f] || after[f]) { out << f << '\n'; break; }
    }
}
