#include <fstream>
#include <queue>
#include <vector>
int main() {
    std::ifstream in("dream.in");
    std::ofstream out("dream.out");
    int n, m;
    in >> n >> m;
    std::vector<int> tile(n * m);
    for (int& t : tile) in >> t;
    const int dr[4] = {-1, 0, 1, 0}, dc[4] = {0, 1, 0, -1};
    std::vector<int> distance(6 * n * m, -1);
    std::queue<int> q;
    distance[0] = 0;
    q.push(0);
    auto step = [&](int cell, int mode, int d) {
        int r = cell / m + dr[d], c = cell % m + dc[d];
        if (r < 0 || r >= n || c < 0 || c >= m) return -1;
        int next = r * m + c, t = tile[next];
        bool smell = mode == 1;
        if (t == 0 || (t == 3 && !smell)) return -1;
        int nextMode = smell ? 1 : 0;
        if (t == 2) nextMode = 1;
        else if (t == 4) nextMode = d + 2;
        return 6 * next + nextMode;
    };
    while (!q.empty()) {
        int state = q.front();
        q.pop();
        int cell = state / 6, mode = state % 6;
        if (cell == n * m - 1) { out << distance[state] << '\n'; return 0; }
        int forced = mode >= 2 ? step(cell, mode, mode - 2) : -1;
        for (int d = 0; d < 4; ++d) {
            if (forced != -1 && d != mode - 2) continue;
            int next = step(cell, mode, d);
            if (next != -1 && distance[next] == -1) {
                distance[next] = distance[state] + 1;
                q.push(next);
            }
        }
    }
    out << -1 << '\n';
}
